	/* @After */
	public void tearDownMine() {
		Msg.debug(this, "Tearing down");
		Msg.debug(this, "Service breakpoints:");
		foreach (LogicalBreakpoint lb in breakpointService.getAllBreakpoints()) {
			Msg.debug(this, "  bp: " + lb);
